263|async function waitForSingleJobSnapshot(cwd, reference, options = {}) {
264|  const timeoutMs = Math.max(0, Number(options.timeoutMs) || DEFAULT_STATUS_WAIT_TIMEOUT_MS);
265|  const pollIntervalMs = Math.max(100, Number(options.pollIntervalMs) || DEFAULT_STATUS_POLL_INTERVAL_MS);
266|  const deadline = Date.now() + timeoutMs;
267|  let snapshot = buildSingleJobSnapshot(cwd, reference);
268|
269|  while (isActiveJobStatus(snapshot.job.status) && Date.now() < deadline) {
270|    await sleep(Math.min(pollIntervalMs, Math.max(0, deadline - Date.now())));
271|    snapshot = buildSingleJobSnapshot(cwd, reference);
272|  }
273|
274|  return {
275|    ...snapshot,
276|    waitTimedOut: isActiveJobStatus(snapshot.job.status),
277|    timeoutMs
278|  };
